int gcdr(int a, int b) { return b == 0 ? (a < 0 ? -a : a) : gcdr(b, a % b); }

class Fraction {
    int n, d;
    void norm();
public:
    Fraction(int num = 0, int den = 1);
    Fraction operator+(const Fraction&) const;
    Fraction operator-(const Fraction&) const;
    Fraction operator*(const Fraction&) const;
    Fraction operator/(const Fraction&) const;
    Fraction operator-() const;
    Fraction& operator++();
    Fraction& operator+=(const Fraction& o);
    Fraction& operator-=(const Fraction& o);
    bool operator<(const Fraction&) const;
    bool operator==(const Fraction&) const;
    bool operator!=(const Fraction&) const;
    Fraction& operator=(const Fraction&);
    int operator[](int i) const;
    string str() const;
};

void Fraction::norm() {
    if (d < 0) { n = -n; d = -d; }
    int g = gcdr(n, d);
    if (g > 1) { n /= g; d /= g; }
}
Fraction::Fraction(int num, int den) : n(num), d(den) { norm(); }
Fraction Fraction::operator+(const Fraction& o) const { return Fraction(n * o.d + o.n * d, d * o.d); }
Fraction Fraction::operator-(const Fraction& o) const { return Fraction(n * o.d - o.n * d, d * o.d); }
Fraction Fraction::operator*(const Fraction& o) const { return Fraction(n * o.n, d * o.d); }
Fraction Fraction::operator/(const Fraction& o) const { return Fraction(n * o.d, d * o.n); }
Fraction Fraction::operator-() const { return Fraction(-n, d); }
Fraction& Fraction::operator++() { n += d; return *this; }
Fraction& Fraction::operator+=(const Fraction& o) { *this = *this + o; return *this; }
Fraction& Fraction::operator-=(const Fraction& o) { *this = *this - o; return *this; }
bool Fraction::operator<(const Fraction& o) const { return n * o.d < o.n * d; }
bool Fraction::operator==(const Fraction& o) const { return n == o.n && d == o.d; }
bool Fraction::operator!=(const Fraction& o) const { return !(*this == o); }
Fraction& Fraction::operator=(const Fraction& o) {
    if (this != &o) { n = o.n; d = o.d; }
    return *this;
}
int Fraction::operator[](int i) const { return i == 0 ? n : d; }
string Fraction::str() const { return to_string(n) + "/" + to_string(d); }

