Mat::Mat() : a{{0, 0}, {0, 0}} {}
Mat::Mat(long long p, long long q, long long r, long long s) : a{{p, q}, {r, s}} {}
Mat Mat::operator*(const Mat& o) const {
    Mat r;
    for (int i = 0; i < 2; i++)
        for (int j = 0; j < 2; j++)
            for (int k = 0; k < 2; k++)
                r.a[i][j] += a[i][k] * o.a[k][j];
    return r;
}
Mat Mat::operator+(const Mat& o) const {
    Mat r;
    for (int i = 0; i < 2; i++)
        for (int j = 0; j < 2; j++) r.a[i][j] = a[i][j] + o.a[i][j];
    return r;
}
Mat Mat::operator-(const Mat& o) const {
    Mat r;
    for (int i = 0; i < 2; i++)
        for (int j = 0; j < 2; j++) r.a[i][j] = a[i][j] - o.a[i][j];
    return r;
}
Mat Mat::operator-() const { return Mat() - *this; }
Mat& Mat::operator=(const Mat& o) {
    if (this != &o)
        for (int i = 0; i < 2; i++)
            for (int j = 0; j < 2; j++) a[i][j] = o.a[i][j];
    return *this;
}
Mat& Mat::operator+=(const Mat& o) { *this = *this + o; return *this; }
Mat& Mat::operator-=(const Mat& o) { *this = *this - o; return *this; }
Mat& Mat::operator++() { a[0][0]++; a[1][1]++; return *this; }
bool Mat::operator==(const Mat& o) const {
    for (int i = 0; i < 2; i++)
        for (int j = 0; j < 2; j++)
            if (a[i][j] != o.a[i][j]) return false;
    return true;
}
bool Mat::operator!=(const Mat& o) const { return !(*this == o); }
long long* Mat::operator[](int i) { return a[i]; }
const long long* Mat::operator[](int i) const { return a[i]; }
void Mat::print() const {
    cout << "[" << a[0][0] << " " << a[0][1] << "; " << a[1][0] << " " << a[1][1] << "]" << endl;
}

Mat mpow(const Mat& m, int e) {
    if (e == 0) return Mat(1, 0, 0, 1);
    Mat half = mpow(m, e / 2);
    Mat r = half * half;
    if (e % 2 == 1) r = r * m;
    return r;
}

