class Poly {
    int c[5];
public:
    Poly();
    Poly(int c0, int c1 = 0, int c2 = 0);
    Poly operator+(const Poly&) const;
    Poly operator-(const Poly&) const;
    Poly operator*(const Poly&) const;
    Poly operator*(int) const;
    Poly operator-() const;
    Poly& operator+=(const Poly&);
    Poly& operator-=(const Poly&);
    Poly& operator=(const Poly&);
    bool operator==(const Poly&) const;
    bool operator!=(const Poly&) const;
    bool operator<(const Poly&) const;
    int& operator[](int);
    int operator[](int) const;
    int degree() const;
    long long eval(int x, int i = 0) const;
    void print() const;
};

Poly::Poly() : c{0, 0, 0, 0, 0} {}
Poly::Poly(int c0, int c1, int c2) : c{c0, c1, c2, 0, 0} {}
Poly Poly::operator+(const Poly& o) const {
    Poly r;
    for (int i = 0; i < 5; i++) r[i] = c[i] + o.c[i];
    return r;
}
Poly Poly::operator-(const Poly& o) const {
    Poly r;
    for (int i = 0; i < 5; i++) r[i] = c[i] - o.c[i];
    return r;
}
Poly Poly::operator*(const Poly& o) const {
    Poly r;
    for (int i = 0; i < 5; i++)
        for (int j = 0; j < 5; j++)
            if (i + j < 5) r[i + j] += c[i] * o.c[j];
    return r;
}
Poly Poly::operator*(int k) const {
    Poly r;
    for (int i = 0; i < 5; i++) r[i] = c[i] * k;
    return r;
}
Poly Poly::operator-() const { return *this * -1; }
Poly& Poly::operator+=(const Poly& o) { *this = *this + o; return *this; }
Poly& Poly::operator-=(const Poly& o) { *this = *this - o; return *this; }
Poly& Poly::operator=(const Poly& o) {
    if (this != &o)
        for (int i = 0; i < 5; i++) c[i] = o.c[i];
    return *this;
}
bool Poly::operator==(const Poly& o) const {
    for (int i = 0; i < 5; i++)
        if (c[i] != o.c[i]) return false;
    return true;
}
bool Poly::operator!=(const Poly& o) const { return !(*this == o); }
bool Poly::operator<(const Poly& o) const {
    if (degree() != o.degree()) return degree() < o.degree();
    for (int i = 4; i >= 0; i--)
        if (c[i] != o.c[i]) return c[i] < o.c[i];
    return false;
}
int& Poly::operator[](int i) { return c[i < 0 ? 0 : (i > 4 ? 4 : i)]; }
int Poly::operator[](int i) const { return c[i < 0 ? 0 : (i > 4 ? 4 : i)]; }
int Poly::degree() const {
    for (int i = 4; i > 0; i--)
        if (c[i] != 0) return i;
    return 0;
}
long long Poly::eval(int x, int i) const {
    if (i > 4) return 0;
    return c[i] + (long long)x * eval(x, i + 1);
}
void Poly::print() const {
    cout << "[";
    for (int i = 0; i < 5; i++) cout << c[i] << (i < 4 ? "," : "");
    cout << "]" << endl;
}

int main() {
