class Str {
    char* s;
    int n;
public:
    Str(const char* t = "");
    Str(const Str&);
    ~Str();
    Str& operator=(const Str&);
    Str operator+(const Str&) const;
    Str& operator+=(const Str&);
    Str operator*(int) const;
    Str operator-() const;
    Str& operator++();
    bool operator==(const Str&) const;
    bool operator!=(const Str&) const;
    bool operator<(const Str&) const;
    char& operator[](int);
    const char& operator[](int) const;
    int length() const;
    const char* c_str() const;
};

Str::Str(const char* t) : s(nullptr), n(0) {
    n = (int)strlen(t);
    s = new char[n + 1];
    strcpy(s, t);
}
Str::Str(const Str& o) : s(new char[o.n + 1]), n(o.n) { strcpy(s, o.s); }
Str::~Str() { delete[] s; }
Str& Str::operator=(const Str& o) {
    if (this != &o) {
        char* t = new char[o.n + 1];
        strcpy(t, o.s);
        delete[] s;
        s = t;
        n = o.n;
    }
    return *this;
}
Str Str::operator+(const Str& o) const {
    Str r;
    delete[] r.s;
    r.n = n + o.n;
    r.s = new char[r.n + 1];
    strcpy(r.s, s);
    strcat(r.s, o.s);
    return r;
}
Str& Str::operator+=(const Str& o) { *this = *this + o; return *this; }
Str Str::operator*(int k) const {
    Str r;
    for (int i = 0; i < k; i++) r += *this;
    return r;
}
Str Str::operator-() const {
    Str r(*this);
    for (int i = 0; i < n; i++) r.s[i] = s[n - 1 - i];
    return r;
}
Str& Str::operator++() {
    for (int i = 0; i < n; i++)
        if (s[i] >= 'a' && s[i] <= 'z') s[i] = s[i] - 32;
    return *this;
}
bool Str::operator==(const Str& o) const { return strcmp(s, o.s) == 0; }
bool Str::operator!=(const Str& o) const { return !(*this == o); }
bool Str::operator<(const Str& o) const { return strcmp(s, o.s) < 0; }
char& Str::operator[](int i) { return s[i]; }
const char& Str::operator[](int i) const { return s[i]; }
int Str::length() const { return n; }
const char* Str::c_str() const { return s; }

