int wrap(int x) {
    const int d = 86400;
    return ((x % d) + d) % d;
}

class Time {
    int s;
public:
    Time(int h = 0, int m = 0, int sec = 0);
    Time operator+(const Time&) const;
    Time operator-(const Time&) const;
    Time operator*(int) const;
    Time operator/(int) const;
    Time operator-() const;
    Time& operator++();
    Time& operator+=(const Time&);
    Time& operator-=(const Time&);
    Time& operator=(const Time&);
    bool operator<(const Time&) const;
    bool operator==(const Time&) const;
    bool operator!=(const Time&) const;
    int operator[](int) const;
    void print() const;
};

Time::Time(int h, int m, int sec) : s(wrap(h * 3600 + m * 60 + sec)) {}
Time Time::operator+(const Time& o) const { Time r; r.s = wrap(s + o.s); return r; }
Time Time::operator-(const Time& o) const { Time r; r.s = wrap(s - o.s); return r; }
Time Time::operator*(int k) const { Time r; r.s = wrap(s * k); return r; }
Time Time::operator/(int k) const { Time r; r.s = s / k; return r; }
Time Time::operator-() const { Time r; r.s = wrap(-s); return r; }
Time& Time::operator++() { s = wrap(s + 1); return *this; }
Time& Time::operator+=(const Time& o) { s = wrap(s + o.s); return *this; }
Time& Time::operator-=(const Time& o) { s = wrap(s - o.s); return *this; }
Time& Time::operator=(const Time& o) { s = o.s; return *this; }
bool Time::operator<(const Time& o) const { return s < o.s; }
bool Time::operator==(const Time& o) const { return s == o.s; }
bool Time::operator!=(const Time& o) const { return s != o.s; }
int Time::operator[](int i) const {
    if (i == 0) return s / 3600;
    if (i == 1) return (s / 60) % 60;
    return s % 60;
}
void Time::print() const {
    cout << setfill('0') << setw(2) << (*this)[0] << ":" << setw(2) << (*this)[1]
         << ":" << setw(2) << (*this)[2] << setfill(' ') << endl;
}

const Time& earliest(const Time* a, int n) {
    if (n == 1) return a[0];
    const Time& r = earliest(a + 1, n - 1);
    return a[0] < r ? a[0] : r;
}

