#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
using namespace std;

class Cplx {
    int re, im;
public:
    Cplx(int r = 0, int i = 0);
    Cplx operator+(const Cplx&) const;
    Cplx operator-(const Cplx&) const;
    Cplx operator*(const Cplx&) const;
    Cplx operator/(int) const;
    Cplx operator-() const;
    Cplx& operator++();
    Cplx& operator+=(const Cplx&);
    Cplx& operator-=(const Cplx&);
    Cplx& operator=(const Cplx&);
    bool operator==(const Cplx&) const;
    bool operator!=(const Cplx&) const;
    bool operator<(const Cplx&) const;
    int& operator[](int);
    const int& operator[](int) const;
    int norm() const;
    string str() const;
};

class Log {
    string buf;
    int count;
public:
    Log();
    Log& operator<<(const Cplx&);
    Log& operator<<(int);
    Log& operator<<(const char*);
    Log& operator<<(char);
    void flush();
};

Cplx::Cplx(int r, int i) : re(r), im(i) {}
Cplx Cplx::operator+(const Cplx& o) const { return Cplx(re + o.re, im + o.im); }
Cplx Cplx::operator-(const Cplx& o) const { return Cplx(re - o.re, im - o.im); }
Cplx Cplx::operator*(const Cplx& o) const {
    return Cplx(re * o.re - im * o.im, re * o.im + im * o.re);
}
Cplx Cplx::operator/(int k) const { return Cplx(re / k, im / k); }
Cplx Cplx::operator-() const { return Cplx(-re, -im); }
Cplx& Cplx::operator++() { ++re; return *this; }
Cplx& Cplx::operator+=(const Cplx& o) { re += o.re; im += o.im; return *this; }
Cplx& Cplx::operator-=(const Cplx& o) { re -= o.re; im -= o.im; return *this; }
Cplx& Cplx::operator=(const Cplx& o) { re = o.re; im = o.im; return *this; }
bool Cplx::operator==(const Cplx& o) const { return re == o.re && im == o.im; }
bool Cplx::operator!=(const Cplx& o) const { return !(*this == o); }
bool Cplx::operator<(const Cplx& o) const {
    if (norm() != o.norm()) return norm() < o.norm();
    return re < o.re;
}
int& Cplx::operator[](int i) { return i == 0 ? re : im; }
const int& Cplx::operator[](int i) const { return i == 0 ? re : im; }
int Cplx::norm() const { return re * re + im * im; }
string Cplx::str() const {
    return to_string(re) + (im < 0 ? "-" : "+") + to_string(im < 0 ? -im : im) + "i";
}

Log::Log() : buf(""), count(0) {}
Log& Log::operator<<(const Cplx& z) { buf += z.str() + " "; ++count; return *this; }
Log& Log::operator<<(int n) { buf += to_string(n) + " "; return *this; }
Log& Log::operator<<(const char* s) { buf += s; buf += " "; return *this; }
Log& Log::operator<<(char ch) { buf += ch; buf += " "; return *this; }
void Log::flush() {
    cout << buf << "(" << count << " complex)" << endl;
    buf.clear();
    count = 0;
}

Cplx sumTo(const Cplx* z, int n) {
    return n == 0 ? Cplx() : z[n - 1] + sumTo(z, n - 1);
}

int main() {
    Cplx a(1, 2), b(3, -1), c;
    Log log;
    log << "a*b=" << a * b << '|' << a + b << a - b << 42;
    log.flush();
    c = a = b;
    log << "chain" << a << c;
    log.flush();
    (a += b) += b;
    ++a;
    log << a << -a << a / 2;
    log.flush();
    c[1] = 8;
    const Cplx k(5, 6);
    log << c << k[0] << k[1];
    log.flush();
    Cplx z[4] = {Cplx(3, 4), Cplx(0, 1), Cplx(-2, 0), Cplx(1, -1)};
    sort(z, z + 4);
    for (int i = 0; i < 4; i++) log << z[i];
    log.flush();
    log << "sum" << sumTo(z, 4);
    log.flush();
    cout << (a == b) << (a != b) << (z[0] < z[1]) << endl;
    return 0;
}
